#include <iostream>

int main() {
    int a{7};
    int* aPtr = &a;

    // Comparing addresses and values
    std::cout << "Value of a: " << a << "\n";
    std::cout << "Value via *aPtr: " << *aPtr << "\n";

    // Verifying & and * as complementary operators
    std::cout << "Address match (&a == aPtr): " << std::boolalpha << (&a == aPtr) << "\n";
    std::cout << "&*aPtr equals aPtr: " << (&*aPtr == aPtr) << "\n";
    std::cout << "*&aPtr equals aPtr: " << (*&aPtr == aPtr) << "\n";

    return 0;
}

#include <iostream>

// Pass-by-value: modifies a local copy, returns modified value
int cubeByValue(int n) {
    return n * n * n;
}

// Simulating pass-by-reference using a pointer (C-style)
void cubeByReference(int* nPtr) {
    if (nPtr != nullptr) {
        *nPtr = (*nPtr) * (*nPtr) * (*nPtr);
    }
}

// Modern C++ pass-by-reference alternative
void cubeByCppRef(int& n) {
    n = n * n * n;
}

int main() {
    int val1 = 5;
    int val2 = 5;
    int val3 = 5;

    val1 = cubeByValue(val1);
    std::cout << "After cubeByValue: " << val1 << "\n";

    cubeByReference(&val2);
    std::cout << "After cubeByReference (pointer): " << val2 << "\n";

    cubeByCppRef(val3);
    std::cout << "After cubeByCppRef (C++ reference): " << val3 << "\n";

    return 0;
}
